/* =====================================================================
 * tyrone-render-card.js
 * Tyrone's 3D house render as ONE self-contained Lovelace card: the
 * complete render page is embedded in this file (base64, below) and the
 * Home Assistant bridge from render-bridge-card is built in, so the
 * render drives real devices and shows real state — no separate render
 * file to host, no iframe URL to maintain.
 *
 * Two element names, same card:
 *   custom:tyrone-render-card   (this package's name)
 *   custom:render-bridge-card   (drop-in alias: existing dashboards
 *                                using the old bridge card keep working)
 *
 * Config:
 *   type: custom:tyrone-render-card
 *   # Bundled mode (default): no url needed — the embedded render is
 *   # served from inside the card. "url: bundled" says the same thing.
 *   # url: https://...  -> legacy url mode: iframe that hosted render
 *   #                      page instead, exactly like the old bridge card.
 *   # height: 600px     -> iframe height (default 600px).
 *
 * Protocol (unchanged from render-bridge-card):
 *   Render -> card : {type:"ha-ready"}
 *                    {type:"ha-action", device, action, value}
 *                    (device "party" + action "toggle": value true =
 *                     start the party, value false = Party Mode off)
 *   Card -> render : {type:"ha-state", devices:{...}, mail:bool,
 *                                     party:bool, <automation name>:{on}}
 *                    {type:"ha-panels", automationsOn, automationsTotal,
 *                                     batteryLowest, offlineCount,
 *                                     haHealth}
 * ===================================================================== */

// Legacy url mode only: fallback render URL when the card config has no
