let _bundledRenderUrl = null;
function bundledRenderUrl() {
  if (_bundledRenderUrl) return _bundledRenderUrl;
  const bin = atob(TWIN_HTML_B64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  _bundledRenderUrl = URL.createObjectURL(new Blob([bytes], { type: "text/html" }));
  return _bundledRenderUrl;
}

